#!/usr/bin/env bash
# env-declared — .env.example keys ↔ env module schema
set -euo pipefail
[ -f .env.example ] || { echo "no .env.example. Creating one enables this check" >&2; exit 3; }
node -e 'const fs=require("fs"),path=require("path"),ex=new Set(fs.readFileSync(".env.example","utf8").split("\n").map(l=>l.replace(/#.*/,"").trim()).filter(l=>l.includes("=")).map(l=>l.split("=")[0].trim())),mods=[],walk=d=>{if(!fs.existsSync(d))return;for(const n of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,n.name);if(n.isDirectory()&&n.name!=="node_modules")walk(p);else if(/^env\.(js|mjs|cjs|ts)$/.test(n.name)&&path.basename(path.dirname(p))==="config")mods.push(p)}};walk(".");walk("services");const schema=new Set(mods.flatMap(f=>[...fs.readFileSync(f,"utf8").matchAll(/required\(\s*["'\''`]([A-Z0-9_]+)["'\''`]\s*\)/g)].map(x=>x[1])));if(!schema.size){console.error("no config/env.* schema keys found");process.exit(1)}const fail=[];for(const k of ex)if(!schema.has(k))fail.push(".env.example has "+k+" missing from env schema");for(const k of schema)if(!ex.has(k))fail.push("env schema has "+k+" missing from .env.example");if(fail.length){console.error(fail.join("\n"));process.exit(1)}'
